spike (asset_id, metric, center_seconds, width_seconds, amount) AS (
    VALUES
        ('docker01', 'cpu_used_percent', 257400, 5400, 58.00),
        ('docker01', 'memory_used_percent', 257400, 5400, 22.00),
        ('docker01', 'temperature_celsius', 257400, 5400, 14.00),
