        ('nas01', 'temperature_celsius', 39600, 21600, 6.00),
        ('media01', 'memory_used_percent', 777600, 7200, 16.00),
        ('media01', 'cpu_used_percent', 777600, 7200, 45.00),
        ('pve01', 'temperature_celsius', 1036800, 4320, 34.00),
        ('pbs01', 'cpu_used_percent', 25200, 5400, 40.00),
        ('pbs01', 'network_rx_bytes_per_sec', 25200, 5400, 60000000.00),
        ('offsite-pbs', 'network_rx_bytes_per_sec', 18000, 10800, 3500000.00)
),
tick AS (
    SELECT g AS sampled_at,
           EXTRACT(EPOCH FROM (NOW() - g))::double precision AS age,
           ((EXTRACT(EPOCH FROM g)::bigint % 86400) / 3600.0)::double precision AS hour_utc
    FROM generate_series(
        to_timestamp((floor(EXTRACT(EPOCH FROM NOW()) / 900) * 900 - 2592000)::double precision),
        to_timestamp((floor(EXTRACT(EPOCH FROM NOW()) / 900) * 900)::double precision),
        INTERVAL '900 seconds'
    ) AS g
)
SELECT p.asset_id,
       p.metric,
       p.unit,
       round(LEAST(p.high::double precision, GREATEST(p.low::double precision,
           p.base::double precision
           + p.swing::double precision * sin((t.hour_utc - 8.0) * pi() / 12.0)
           - p.growth::double precision * (t.age / 2592000.0)
           + COALESCE((
               SELECT sum(s.amount::double precision
                          * exp(-8.0 * power((s.center_seconds::double precision - t.age) / s.width_seconds::double precision, 2.0)))
               FROM spike s
               WHERE s.asset_id = p.asset_id AND s.metric = p.metric
             ), 0.0)
           + p.noise::double precision * (random() + random() + random() - 1.5) * 1.15
       ))::numeric, 2)::double precision,
       t.sampled_at
FROM profile p
CROSS JOIN tick t
WHERE t.age >= p.stop_seconds::double precision
ORDER BY p.asset_id, p.metric, t.sampled_at;

