INSERT INTO incidents (id, title, summary, status, severity, source, group_id, primary_asset_id, assignee, created_by, opened_at, mitigated_at, resolved_at, closed_at, root_cause, action_items, lessons_learned, metadata, created_at, updated_at) VALUES
    ('incident-nas01-disk', 'Disk nearly full on nas01', 'Pool tank on nas01 passed 90% used 18 hours ago and is at 91%. Snapshot retention on tank/vms and tank/backups was cut from 30 to 14 days, which freed 2.1 TB. Two 16 TB disks are ordered to widen the pool.', 'open', 'critical', 'alert_auto', 'grp-storage', 'nas01', NULL, 'system', NOW() - INTERVAL '64500 seconds', NULL, NULL, NULL, '', '[]'::jsonb, '', '{}'::jsonb, NOW() - INTERVAL '64500 seconds', NOW() - INTERVAL '3600 seconds'),
    ('incident-workstation-offline', 'Device offline on workstation', 'workstation stopped reporting 3 hours ago. Its last log lines show NVMe timeouts and a suspend. CI jobs that used its runner now wait for ci-runner.', 'open', 'critical', 'alert_auto', 'grp-desks', 'workstation', NULL, 'system', NOW() - INTERVAL '10200 seconds', NULL, NULL, NULL, '', '[]'::jsonb, '', '{}'::jsonb, NOW() - INTERVAL '10200 seconds', NOW() - INTERVAL '3600 seconds'),
    ('incident-k3s-cert-manager', 'cert-manager webhook crash loop on k3s-cp1', 'The cert-manager webhook pod has been in CrashLoopBackOff since the Helm upgrade to chart 1.16.2. Certificate renewals for ingress are blocked until it runs again.', 'investigating', 'medium', 'manual', 'grp-services', 'k3s-cp1', NULL, (SELECT id FROM users WHERE username = 'demo'), NOW() - INTERVAL '6600 seconds', NULL, NULL, NULL, '', '[]'::jsonb, '', '{}'::jsonb, NOW() - INTERVAL '6600 seconds', NOW() - INTERVAL '1800 seconds'),
    ('incident-docker01-restart-loop', 'Container restart loop on docker01', 'A scheduled image update hit the registry''s pull rate limit. 9 of 13 containers on docker01 restarted in a loop for about an hour.', 'resolved', 'high', 'manual', 'grp-services', 'docker01', NULL, (SELECT id FROM users WHERE username = 'demo'), NOW() - INTERVAL '258600 seconds', NOW() - INTERVAL '255600 seconds', NOW() - INTERVAL '248400 seconds', NULL, 'The weekly image update pulled every image at once and the registry answered 429. Compose restart policies then restarted each container that had no image.', '["Pin images by digest in every stack","Run a pull-through registry cache on docker01","Update one stack at a time"]'::jsonb, 'Image updates need a pause between stacks.', '{}'::jsonb, NOW() - INTERVAL '258600 seconds', NOW() - INTERVAL '248400 seconds'),
    ('incident-vyos-image-update', 'Network down after VyOS image update', 'The LAN was down for 45 minutes after vyos rebooted into image 1.4.1. The network came back after booting the previous image from the console.', 'resolved', 'critical', 'manual', 'grp-network', 'vyos', NULL, (SELECT id FROM users WHERE username = 'demo'), NOW() - INTERVAL '432000 seconds', NOW() - INTERVAL '429300 seconds', NOW() - INTERVAL '424800 seconds', NULL, 'The r8169 network driver in image 1.4.1 fails on the LAN port''s Realtek chip.', '["Hold vyos on image 1.4.0","Add the serial console steps to the update checklist","Schedule router updates inside a maintenance window"]'::jsonb, 'Keep a console path to the router that does not need the LAN.', '{}'::jsonb, NOW() - INTERVAL '432000 seconds', NOW() - INTERVAL '424800 seconds')
