    ('saved-docker-prune', 'Prune Docker images', 'Remove images no container uses.', '[{"name":"Prune on docker01","command":"docker image prune -af","target":"docker01"},{"name":"Prune on media01","command":"docker image prune -af","target":"media01"},{"name":"Prune on monitor01","command":"docker image prune -af","target":"monitor01"}]'::jsonb, (SELECT id FROM users WHERE username = 'demo'), NOW() - INTERVAL '3110400 seconds'),
