    ('saved-pve-guests', 'List Proxmox guests', 'VMs and their state on both nodes.', '[{"name":"Guests on pve01","command":"qm list","target":"pve01"},{"name":"Guests on pve02","command":"qm list","target":"pve02"}]'::jsonb, (SELECT id FROM users WHERE username = 'demo'), NOW() - INTERVAL '2419200 seconds'),
